(() => {
  'use strict';
  const C=OSLabConcurrencyMovies, P=C.phase, E=C.esc, pick=C.select, badge=C.badge, node=C.node;
  const page=document.body.dataset.page;
  const chosen=(attr,value)=>document.querySelector('['+attr+'="'+value+'"]')?.click();
  function counter(){
    const detail=C.wrap('count-flow',['#counter-demo'],'手动安排线程与逐操作回查');
    C.mount({id:'count-flow',before:detail,controls:['[data-lock-mode]','[data-order]'],
      action:()=>{const mode=pick('data-lock-mode','none');if(page==='locks')chosen('data-lock-mode',mode==='atomic'?'naive':'atomic');else chosen('data-order',pick('data-order','interleaved')==='interleaved'?'serial':'interleaved');},
      actionLabel:()=>page==='locks'?pick('data-lock-mode','atomic')==='atomic'?'对照错误获取':'改用原子获取':'对照另一种次序',
      build(){const mode=pick('data-lock-mode','none'),order=pick('data-order','interleaved'),frames=OSLabConcurrency.replay(mode,OSLabConcurrency.schedule(mode,order));
        const phases=[P(frames[0],'两次加 1，完成计数应当变为 2','共享的 count 只有一份；每个线程的寄存器各保存一份计算用的副本。',{duration:1100})];
        let showedWait=false;
        frames.forEach((s,i)=>{if(!i)return;const before=frames[i-1],op=s.operation,who=s.actor,t=s.threads.find(t=>t.id===who),props={before,id:'frame-'+i,focus:who,duration:1000};let title,note,moves=[];
          if(s.attempts>before.attempts){if(showedWait)return;showedWait=true;title=who+' 被挡在锁外，不能读取 count';note='持锁者完成整段更新并释放锁后，等待者才能继续。';}
          else if(op==='读取 count'){title=who+' 读入 '+t.register+'，共享 count 仍是 '+s.count;note='读取产生副本，没有把共享变量取走。两个寄存器可以同时留着相同的旧值。';moves=[{from:'count',to:'reg-'+who,text:t.register,type:'cm-copy'}];props.during=who+' 正把 count 读入自己的寄存器';}
          else if(op==='寄存器加 1'){title=who+' 在自己的副本上加 1，得到 '+t.register;note='运算发生在这个线程的寄存器里；尚未写回，所以共享 count 没有改变。';}
          else if(op==='写回 count'){title=who+' 写回 '+s.count+(before.count===s.count?'，覆盖了相同的值':'，共享 count 更新');note=before.count===s.count?'B 用的仍是旧值算出的结果，第二次写回没有再增加 count。':'这次写回才真正改变共享变量，另一线程的副本不会自动跟着更新。';moves=[{from:'reg-'+who,to:'count',text:s.count,type:'cm-copy'}];props.during=who+' 正把 '+s.count+' 写回 count';}
          else if(op==='检查锁标志'){title=who+' 检查到锁空闲，但还没有占用';note='检查和设置是两个独立操作，因此其他线程仍可能读到同一个“空闲”标志。';}
          else if(op==='设置锁标志'){title=s.holders.length>1?'A、B 都进入了临界区，锁失效':who+' 设置占用标志，进入临界区';note=s.holders.length>1?'两个线程先前都通过了检查，后来都设置为“占用”。标志为 1 并不代表只有一个持有者。':'把标志改成占用，不能撤销另一个线程先前作出的判断。';}
          else if(op==='原子地获取锁'){title=who+' 原子地取得锁';note='读取旧值和设置占用合为一步，成功者进入，其他获取者被挡在外面。';}
          else {if(i!==frames.length-1&&mode!=='atomic')return;title=who+' 释放锁';note='整段更新已结束，下一位获取者才能基于新的共享值继续。';props.duration=700;}
          phases.push(P(s,title,note,{...props,moves}));
        });const end=frames.at(-1);phases.push(P(end,end.count===2?'两次更新都保留了：count = 2':'两项工作已完成，count 却只有 1',end.violation?'错误获取曾让 A、B 同时进入临界区。需要原子获取，并保护完整更新。':end.count===2?'后一个线程在前一个线程写好的值上继续加 1。':'A、B 都从 0 算出 1；后一次写回覆盖前一次结果，丢失了一次更新。',{duration:1000,id:'result'}));return{context:mode==='none'?'共享变量与线程副本':mode==='naive'?'错误方案：检查与设置分开':'原子获取，保护整段更新',phases,mode};},
      view(s){return '<div class="cm-counter" data-lost="'+(s.threads.every(t=>t.done)&&s.count!==2)+'" data-owner="'+(s.holders.length===1?s.holders[0]:'')+'" data-violation="'+s.violation+'"><div class="cm-counter-guard"></div>'+s.threads.map(t=>'<div class="cm-counter-thread cm-side-'+t.id+'">'+badge(t.id)+'<span>'+(s.mode==='naive'&&t.pc>0?'检查时：空闲':'线程 '+t.id)+'</span>'+node('reg-'+t.id,'自己的寄存器',t.register??'—','cm-register')+'<small>'+ (t.done?'更新结束':s.holders.includes(t.id)?'已进入临界区':s.mode==='atomic'&&s.flag?'等待锁，不能进入':'准备更新')+'</small></div>').join('')+'<div class="cm-counter-shared">'+node('count','共享 count',s.count,'cm-memory')+'<span>两次更新的预期：2</span></div><div class="cm-counter-rule">'+(s.mode==='none'?'没有互斥保护':s.violation?'曾经同时进入：A 与 B':s.flag?'锁由 '+s.holders.join('、')+' 持有':'锁空闲')+'</div><div class="cm-operation-strip"><span>读取副本</span><span>寄存器加 1</span><span>写回共享变量</span></div></div>';}
    });
  }
  function lifecycle(){const section=document.getElementById('lifecycle');const detail=C.wrap('life-flow',[section.querySelector('.cc-lifecycle'),section.querySelector('.cc-log'),section.querySelector('.cc-transport')],'接口执行与线程状态回查');
    C.mount({id:'life-flow',before:detail,controls:['[data-life]'],action:()=>chosen('data-life',pick('data-life','early')==='early'?'late':'early'),actionLabel:()=> '对照另一种完成次序',
      build(){const mode=pick('data-life','early'),frames=OSLabThreadLifecycle.traces[mode];let written=false;const phases=frames.map((s,i)=>{written ||= s.wc==='result = 42';const title=s.mc.includes('读取 result')?'join 返回，主线程读取结果':s.worker==='已结束'?'工作线程已结束，结果仍然保留':written?'42 已写入，工作线程尚未结束':s.main==='阻塞'?'主线程停在 join，等待工作线程结束':i?'工作线程已创建，两条执行流都可以运行':'主线程尚未创建工作线程';const note=i===1?'创建新的执行流后，两条线程可以分别获得 CPU。创建成功并不意味着工作已经做完。':s.text;return P({...s,written,returned:s.mc.includes('读取 result')},title,note,{duration:i?1500:1000,id:'frame-'+i,moves:s.mc.includes('读取 result')?[{from:'life-result',to:'life-main-use',text:'42',type:'cm-copy'}]:[],during:'主线程越过 join，读取工作线程的结果'});});return{context:'join 等的是线程结束，不只是结果写入',phases};},
      view(s){return '<div class="cm-life"><div class="cm-life-main">'+badge('A','主')+'<strong>主线程</strong><div class="cm-join '+(s.main==='阻塞'?'cm-stop':'')+'">join '+(s.returned?'已返回':s.main==='阻塞'?'等待中':s.mc==='join 尚未返回'?'尚未返回':'尚未调用')+'</div>'+node('life-main-use','读取结果',s.returned?'42':'—','cm-register')+'</div><div class="cm-life-worker '+(s.worker==='尚未创建'?'cm-unborn':'')+'">'+badge('B','工')+'<strong>工作线程</strong><div class="cm-work-state">'+E(s.worker)+'</div>'+node('life-result','共享结果',s.written?'42':'未写入','cm-memory')+'</div><div class="cm-life-link">'+(s.worker==='已结束'?'工作线程已结束，join 可以返回':s.written?'结果虽已写入，线程尚未结束':s.worker==='尚未创建'?'create 创建新的执行流':'两个线程可以分别获得执行机会')+'</div></div>';}
    });
  }
  function deadlock(){const detail=C.wrap('dead-flow',['#dead-demo'],'锁持有者与逐操作回查');C.mount({id:'dead-flow',before:detail,controls:['[data-dead-policy]','[data-dead-order]'],action:()=>chosen('data-dead-policy',pick('data-dead-policy','opposite')==='opposite'?'ordered':'opposite'),actionLabel:()=>pick('data-dead-policy','opposite')==='opposite'?'统一获取次序':'对照相反次序',
    build(){const policy=pick('data-dead-policy','opposite'),frames=OSLabDeadlock.trace(policy,pick('data-dead-order','interleaved'));const phases=frames.map((s,i)=>{const prev=frames[i-1],changes=prev?Object.keys(s.locks).filter(k=>s.locks[k]!==prev.locks[k]):[];const moves=changes.map(k=>({from:prev.locks[k]?prev.locks[k]+'-'+k:'free-'+k,to:s.locks[k]?s.locks[k]+'-'+k:'free-'+k,text:k,type:'cm-key',remove:true}));return P(s,s.deadlock?'双方都在等对方的锁，谁也走不到释放操作':s.op==='work'?s.actor+' 凑齐两把锁，完成工作':s.actor?s.actor+(s.threads[s.actor].wait?' 被对方持有的锁挡住':s.op==='unlock'?' 释放 '+changes[0]:' 取得 '+changes[0]):'A、B 都要拿齐 L1、L2 才能工作',s.deadlock?'A 留着 L1 等 L2；B 留着 L2 等 L1。两把锁的持有者也都在等待。':s.log,{duration:i?1400:1100,before:prev,moves,id:'frame-'+i,during:s.actor+(s.op==='unlock'?' 正在释放锁':' 正在取得锁'),duringNote:s.op==='unlock'?'完成工作的线程正在归还锁，其他线程随后才有机会取得它。':'锁正在交给 '+s.actor+'；取得两把锁后，线程才能开始工作。'});});const last=frames.at(-1);if(!last.deadlock)phases.push(P(last,'两条线程都完成，锁已归还',policy==='ordered'?'等待 L1 的线程没有占住 L2，先拿到 L1 的线程可以凑齐资源并完成。':'这次依次运行没有形成死锁，但相反获取次序的风险仍在。',{duration:1100,id:'result'}));return{context:policy==='ordered'?'A、B 都按 L1 → L2 获取':'A：L1 → L2；B：L2 → L1',phases};},
    view(s){const edges=OSLabDeadlock.dependencies(s);return '<div class="cm-dead" data-cycle="'+s.deadlock+'"><div class="cm-key-bank"><span>空闲锁</span>'+['L1','L2'].map(k=>'<span class="cm-key-slot" data-node="free-'+k+'">'+(!s.locks[k]?'<b class="cm-key">'+k+'</b>':'')+'</span>').join('')+'</div>'+['A','B'].map(w=>'<div class="cm-dead-owner cm-side-'+w+'">'+badge(w)+'<strong>线程 '+w+'</strong><div class="cm-held-keys">'+['L1','L2'].map(k=>'<span class="cm-key-slot" data-node="'+w+'-'+k+'">'+(s.locks[k]===w?'<b class="cm-key">'+k+'</b>':'')+'</span>').join('')+'</div><p>'+E(s.threads[w].done?'已完成':s.threads[w].wait?'等待 '+s.threads[w].wait:s.threads[w].pc>=3?'工作已做完，正在归还锁':Object.values(s.locks).filter(owner=>owner===w).length===2?'已凑齐两把锁':Object.values(s.locks).includes(w)?'还需要另一把锁':'尚未取得锁')+'</p></div>').join('')+'<div class="cm-dead-arrows">'+edges.map(e=>'<div class="cm-wait-arrow '+(e.from==='B'?'cm-arrow-back':'')+'"><span>'+e.from+' 等 '+e.lock+'</span><i></i></div>').join('')+'</div><div class="cm-dead-result">'+(s.deadlock?'相互等待，无法继续':'已完成 '+s.completed+' / 2')+'</div></div>';}
  });}
  function approximation(){const detail=C.wrap('approx-flow',['#approx-demo'],'每次本地更新与合并记录');C.mount({id:'approx-flow',before:detail,controls:['[data-threshold]'],action:()=>chosen('data-threshold',pick('data-threshold','4')==='4'?'1':'4'),actionLabel:()=>pick('data-threshold','4')==='4'?'对照每次都合并':'改为累计 4 次',
    build(){const threshold=Number(pick('data-threshold','4')),frames=OSLabConcurrentStructures.counterTrace(threshold);const phases=frames.map((s,i)=>{const before=frames[i-1],merge=s.phase==='merge',amount=merge?before.locals[s.cpu]:1;return P(s,!i?'更新先在本地累计':merge?'把 '+amount+' 次更新一起合并到全局':'CPU '+s.cpu+' 的本地计数加 1',!i?'当前尚未更新，本地计数和全局计数都为 0。接下来先在本地累计，达到阈值后再合并到全局。':merge?'全局锁只获取一次，这一批本地计数转入全局后清零。':'本地的更新已经完成，但只读全局值还看不到这些更新。',{duration:!i?1000:merge?820:520,travel:merge?600:350,before,moves:i?[{from:merge?'local-'+s.cpu:'add-'+s.cpu,to:merge?'global':'local-'+s.cpu,text:merge?'+'+amount:'+1',type:'cm-count-dot'}]:[],during:merge?'一批 '+amount+' 次更新正在合并':'一次更新正在计入本地',duringNote:merge?'把本地累计的一批更新加入全局计数；合并完成后清空这份本地计数。':'本次更新先增加本地计数；未合并到全局前，只读全局值看不到它。',id:'frame-'+i});});const last=frames.at(-1);phases.push(P(last,'实际完成 12 次；全局读数为 '+last.global,last.total>last.global?'剩余 '+(last.total-last.global)+' 次更新还在本地，没有丢失。全局锁获取 '+last.merges+' 次，而逐次合并需要 12 次。':'结束时全部已合并。全局锁获取 '+last.merges+' 次；运行中仍有本地更新尚未合并的时刻。',{duration:1200,id:'result'}));return{context:'本地阈值 '+threshold+'；两颗 CPU 各更新 6 次',phases,threshold};},
    view(s,{story}){return '<div class="cm-approx"><div class="cm-local-row">'+s.locals.map((n,i)=>'<div class="cm-local"><span data-node="add-'+i+'">'+badge('A','CPU '+i)+' 更新</span>'+node('local-'+i,'尚未合并',n,'cm-bowl')+'<div class="cm-dot-row">'+Array.from({length:story.threshold},(_,j)=>'<i class="'+(j<n?'cm-dot-on':'')+'"></i>').join('')+'</div></div>').join('')+'</div><div class="cm-global-row">'+node('global','全局计数',s.global,'cm-memory')+'<div><strong>实际完成 '+s.total+' / 12</strong><span>本地还留着 '+(s.total-s.global)+' 次</span><span>全局加锁 '+s.merges+' 次</span></div></div></div>';}
  });}
  if(page==='threads'){lifecycle();counter();}if(page==='locks')counter();if(page==='deadlock')deadlock();if(page==='concurrentStructures')approximation();
})();
